const input=$json.body??$json;
const s=v=>String(v??"").trim();
const silence=input.silence??input.reengagement??input;
const strategy=input.strategy??{};
const intent=s(input.intent??strategy.intent).toLowerCase();
const action=s(input.next_action??silence.action?.next_action??silence.action).toLowerCase();
const channel=s(input.channel??silence.action?.next_channel??input.last_channel).toLowerCase()||"sms";
const sellerName=s(input.seller_name??input.first_name??input.lead?.first_name);
const propertyAddress=s(input.property_address??input.address??input.property?.address);
const motivation=s(input.motivation??strategy.motivation).toLowerCase();
const days=Number(input.days_since_last_contact??silence.evidence?.days_since_last_contact??0);
const attempts=Number(input.contact_attempts??silence.evidence?.contact_attempts??0);
const dnc=input.dnc===true||input.dnc_suppressed===true||intent==="opt_out"||action==="suppress";
const leadId=s(input.lead_id??input.identity?.lead_id), dealId=s(input.deal_id??input.identity?.deal_id), threadId=s(input.thread_id??input.identity?.thread_id);
const missing=[]; if(!leadId&&!dealId)missing.push("lead_id_or_deal_id"); if(!threadId)missing.push("thread_id"); if(!sellerName)missing.push("seller_name");
let purpose="check_in", tone="low_pressure", body="";
const subjectMap={nurture_recycle:"Closing the loop",fresh_value_proposition:"Checking back in",soft_check_in:"Quick check-in",light_follow_up:"Quick follow-up"};
if(dnc){body="";}
else if(action==="stop_active_pursuit"){purpose="nurture_recycle"; tone="respectful"; body=(sellerName?"Hi "+sellerName+", I wanted to close the loop for now. I know timing can change, so if selling becomes a priority later, feel free to reach back out. Wishing you the best.":"I wanted to close the loop for now. I know timing can change, so if selling becomes a priority later, feel free to reach back out. Wishing you the best.");}
else if(action==="reengage_with_new_angle"||action==="change_channel_and_message"){purpose="fresh_value_proposition"; tone="helpful"; body=(sellerName?"Hi "+sellerName+", just checking back in. I know things can change, so I wanted to see if selling "+(propertyAddress?"the property at "+propertyAddress:"your property")+" is still something you may consider. If it is, I can give you a straightforward idea of what the options look like—no pressure.":"Just checking back in. I know things can change, so I wanted to see if selling "+(propertyAddress?"the property at "+propertyAddress:"your property")+" is still something you may consider. If it is, I can give you a straightforward idea of what the options look like—no pressure.");}
else if(action==="soft_reengage"){purpose="soft_check_in"; tone="casual"; body=(sellerName?"Hi "+sellerName+", just wanted to check in and see if selling "+(propertyAddress?"the property at "+propertyAddress:"your property")+" is still on your radar. No rush—just let me know either way.":"Just wanted to check in and see if selling "+(propertyAddress?"the property at "+propertyAddress:"your property")+" is still on your radar. No rush—just let me know either way.");}
else {purpose="light_follow_up"; tone="low_pressure"; body=(sellerName?"Hi "+sellerName+", just checking in to see if you had any questions or if there is anything I can help with regarding "+(propertyAddress?"the property at "+propertyAddress:"your property")+".":"Just checking in to see if you had any questions or if there is anything I can help with regarding "+(propertyAddress?"the property at "+propertyAddress:"your property")+".");}
if(/foreclosure|tax|urgent|moving/.test(motivation))tone="time_sensitive_but_non_pressure";
const subject=subjectMap[purpose]||"Quick follow-up";
const actionId="seller-reengagement-message:"+((threadId||leadId||dealId||"unknown"))+":"+(input.request_id||input.action_id||"event")+":v1";
return[{json:{ok:missing.length===0&&!dnc,blocked:dnc,reason:dnc?"DNC/opt-out active":missing.length?"required identity/context missing":"message generated from grounded seller context",message:{action_id:actionId,channel,subject,body,purpose,tone,personalized:sellerName!==""&&propertyAddress!=="",deterministic:true},identity:{lead_id:leadId||null,deal_id:dealId||null,thread_id:threadId||null},evidence:{days_since_last_contact:days,contact_attempts:attempts,source_action:action||null},routing:{next_workflow:dnc?null:"wf-082-autonomous-communication-dispatch",dispatch_mode:dnc?"blocked":"approval_or_authorized_dispatch"},missing_requirements:missing}}];
